canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(tab!=='base')return;if(buildOpen){buildOpen=false;render();return;}$('.command-more')?.removeAttribute('open');$('#nav-more').hidden=true;$('.camera-more')?.removeAttribute('open');canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect(),p={x:e.clientX-r.left,y:e.clientY-r.top};pointers.set(e.pointerId,p);if(pointers.size===2){const[a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:renderer.camera.zoom};start=null;box=null;return;}start={...p,button:e.button,building:!!G.STRUCTURES[tool],road:tool?.startsWith('road-'),pan:!tool?.startsWith('road-')&&(e.button===1||e.altKey||mode==='pan'||e.pointerType==='touch'&&mode!=='boxSelect'&&!G.STRUCTURES[tool]),shift:e.shiftKey};last=p;dragged=false;});
