addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('#modal').open)return;const key=e.key.toLowerCase();if(key==='enter'&&G.STRUCTURES[tool]){document.querySelector('[data-action="confirm-building"]')?.click();return;}if(key==='r'&&G.STRUCTURES[tool]){buildingRotation=(buildingRotation+1)%4;renderDock();return;}if(key==='b'){const was=buildOpen;chooseTab('base');buildOpen=!was;render();return;}if(key==='q'||key==='e'){renderer.rotate?.(key==='q'?-Math.PI/4:Math.PI/4);return;}if(key==='escape'){tool=null;mode='select';chooseTab('base');}if(key==='a'){mode='attackMove';renderDock();}if(key==='m'){mode='move';renderDock();}if(key==='s')act(G.order(state,selected,'hold'));if(key==='g'){mode='gather';renderDock();}if(key===' '){e.preventDefault();center();}if(/^[1-9]$/.test(key)){e.preventDefault();if(e.ctrlKey)groups[key]=[...selected];else selected=(groups[key]||[]).filter(id=>G.units(state).some(u=>u.id===id));render();}});
